begin;
truncate late_test.checks;
do $$declare x jsonb;y jsonb;w jsonb;z jsonb;r jsonb;p jsonb;f uuid;origin uuid;k uuid;so uuid;sl uuid;begin
 x:=output4_test.context('Replacement');f:=(x->>'factory')::uuid;origin:=(x->>'item')::uuid;
 w:=output4_test.decision(x,'REPLACE',10);
 perform late_test.ok((select quantity_available=10 and warehouse_quantity=10 from public.unfinished_lots where id=(x->>'lot')::uuid),'replacement retains original physical material');
 perform late_test.ok(private.output_demand_received(f,origin)=90,'replacement decision does not fulfill');
 perform late_test.ok(public.manufactured_completion_read(f)#>>'{rows,0,free_for_stock}'='10','replacement frees only its source allocation');
 y:=output4_test.start(x,w);
 r:=public.record_manufactured_output(f,output2_test.payload(y,10),gen_random_uuid());
 perform late_test.ok(private.output_demand_received(f,origin)=90,'replacement Good is not received demand');
 perform output4_test.receive(f,(r->>'entry_id')::uuid);perform public.finish_product_item(f,(w->>'item_id')::uuid);
 perform late_test.ok(private.output_demand_received(f,origin)=100,'replacement receipt fulfills original ten');
 x:=x||jsonb_build_object('revision',5);w:=output4_test.decision(x,'STOCK',10);y:=output4_test.start(x,w);
 r:=public.record_manufactured_output(f,output2_test.payload(y,9)||jsonb_build_object('input_lot',x->>'lot','input_quantity',10,'discarded_quantity',1,'scrap_kg',0.25),gen_random_uuid());
 perform output4_test.receive(f,(r->>'entry_id')::uuid);perform public.finish_product_item(f,(w->>'item_id')::uuid);
 perform late_test.ok(private.output_demand_received(f,origin)=100,'later stock recovery never fulfills original twice');
 perform late_test.ok((select on_hand=109 from public.finished_goods_balances where factory_id=f and product_id=(x->>'product')::uuid),'100 demand plus nine stock; actual yield conserved');
 perform late_test.ok((select quantity_available=0 and warehouse_quantity=0 from public.unfinished_lots where id=(x->>'lot')::uuid),'original material consumed exactly once');
 perform late_test.ok((select effective_scrap_kg=.25 and effective_scrap=1 from public.production_entries where id=(r->>'entry_id')::uuid),'discarded unit separate from Scrap KG');
 perform late_test.fails(format('select public.plan_manufactured_completion(%L,%L,%L,5,%L)',f,x->>'output',jsonb_build_object('group_id',x->>'group','quantity','1','choice','STOCK','operations',jsonb_build_array(x->>'step1'),'reason','Duplicate stock recovery'),gen_random_uuid()),'output_allocation_unavailable');

 x:=output4_test.context('Partial operations',true);f:=(x->>'factory')::uuid;origin:=(x->>'item')::uuid;
 w:=output4_test.decision(x,'COMPLETE',10,jsonb_build_array(x->>'step1'));y:=output4_test.start(x,w);
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,output2_test.payload(y,10)||jsonb_build_object('input_lot',x->>'lot','input_quantity',10),gen_random_uuid()),'output_operations_remaining');
 p:=output2_test.payload(y,0,10)||jsonb_build_object('input_lot',x->>'lot','input_quantity',10);
 p:=jsonb_set(p,'{output_groups}',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'quantity','10','missing_operations',jsonb_build_array(x->>'step2'))));
 r:=public.record_manufactured_output(f,p,gen_random_uuid());z:=output4_test.receive(f,(r->>'entry_id')::uuid);perform public.finish_product_item(f,(w->>'item_id')::uuid);
 perform late_test.ok((select quantity_available=0 from public.unfinished_lots where id=(x->>'lot')::uuid) and (select quantity_available=10 and warehouse_quantity=10 from public.unfinished_lots where id=(z->>'lot')::uuid),'partial operations relocate same ten, no duplicate WIP');
 perform late_test.ok(private.output_demand_received(f,origin)=90,'unfinished receipt does not fulfill finished demand');
 perform late_test.ok((select demand_item_id=origin and classification->'missing_operations'=jsonb_build_array(x->>'step2') from private.manufactured_output_lots where lot_id=(z->>'lot')::uuid),'remaining operation and original demand follow genealogy');
 y:=x||z;w:=output4_test.decision(y,'COMPLETE',10,jsonb_build_array(x->>'step2'));
 perform late_test.fails(format('select public.plan_product_item(%L,%L,%L,%L)',f,w->>'item_id',x->>'line',date_trunc('day',clock_timestamp())+interval '6 days'),'output_work_capability');
 y:=output4_test.start(y||jsonb_build_object('line',x->>'other_line'),w);
 r:=public.record_manufactured_output(f,output2_test.payload(y,10)||jsonb_build_object('input_lot',z->>'lot','input_quantity',10),gen_random_uuid());perform output4_test.receive(f,(r->>'entry_id')::uuid);perform public.finish_product_item(f,(w->>'item_id')::uuid);
 perform late_test.ok(private.output_demand_received(f,origin)=100,'two-operation chain fulfills original once');
 perform late_test.ok((select coalesce(sum(quantity_available),0)=0 from public.unfinished_lots where factory_id=f),'all intermediate input consumed without duplicates');

 x:=output4_test.context('Split allocations');f:=(x->>'factory')::uuid;
 w:=output4_test.decision(x,'COMPLETE',4);y:=output4_test.start(x,w);x:=x||jsonb_build_object('revision',5);
 z:=output4_test.decision(x,'REPLACE',6);
 perform late_test.ok((select warehouse_quantity=6 and quantity_available=10 from public.unfinished_lots where id=(x->>'lot')::uuid),'issued four does not hide stored six');
 perform late_test.ok(public.manufactured_completion_read(f)#>>'{rows,0,free_for_stock}'='6','replacement releases six only');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 perform late_test.fails(format('select output4_test.decision(%L,''STOCK'',1)',x||jsonb_build_object('revision',6)),'permission_denied');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.ok((select count(*)=2 from private.manufactured_completion_work where factory_id=f),'denied decision creates no work');
 perform late_test.ok(not has_function_privilege('anon','public.plan_manufactured_completion(uuid,uuid,jsonb,bigint,uuid)','execute') and not has_table_privilege('authenticated','private.manufactured_completion_work','insert'),'private work and RPC grants protected');
 perform late_test.ok((public.manufactured_output_capability(f)->>'available')='false','shipped capability stays disabled');
end$$;
set constraints all immediate;
select count(*) assertions from late_test.checks;
rollback;
